nextflow_process {

    name "Test Process SAMTOOLS_VIEW"
    script "../main.nf"
    config "./nextflow.config"
    process "SAMTOOLS_VIEW"

    tag "modules"
    tag "modules_nfcore"
    tag "samtools"
    tag "samtools/view"

    test("bam") {
        when {
            params {
                samtools_args = ""
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.bam', checkIfExists: true),
                    []
                ]
                input[1] = [[],[],[]]
                input[2] = [[], []]
                input[3] = [[], []]
                input[4] = []
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"])).match()}
            )
        }
    }

    test("bam_csi_index") {
        when {
            params {
                samtools_args = "--output-fmt bam --write-index"
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                    []
                ]
                input[1] = [[],[],[]]
                input[2] = [[], []]
                input[3] = [[], []]
                input[4] = 'csi'
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"], unstableKeys: ["csi"])).match()}
            )
        }
    }

