                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                    []
                ]
                input[1] = [[],[],[]]
                input[2] = channel.of('testN:1')
                    .collectFile(name: 'selected_reads.txt')
                    .map { file -> [[:], file] }
                input[3] = [[], []]
                input[4] = 'bai'
                """
            }
        }

        then {
            assert process.success
            assertAll(
                // bam is empty so we checksum the name
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["unselected"], unstableKeys: ["bam","bai", "unselected_index"])).match()}
            )
        }
    }

